-- cash_balances - NEW - OFFLINE DATABASE ONLY
--
-- DO NOT RUN THIS ON THE ONLINE SERVER.
--   The online database has its own version of this view, written a different way
--   but already correct and already fast. Running this there would replace a
--   working view for no gain. Only the offline database ever had the bad one.
--
-- WHAT IT FIXES
--   The old view hung two unrelated branches off cashaccount:
--       cashaccount -> cashaction -> cashaction_denominations
--       cashaccount -> cashaccount_subproject -> subproject -> account -> till
--   Nothing connects them, so the server built their cross product and let the
--   GROUP BY collapse it again: 6,304,983 rows built to return 781.
--   The cash branch is now totalled in its own derived table and joined once,
--   which is how the action side was already written.
--
--       cash_balances       23,215 ms ->   131 ms
--       get_cash_report()   70,412 ms ->   475 ms
--
-- VERIFIED
--   781 rows x 21 columns identical, plus every query the application issues, for
--   all 19 cash accounts. Confirmed independently by the user before this file was
--   written.
--
-- IT ALSO RESTORES THE DEFINER
--   The live offline view currently says jj@localhost, because that is the user
--   that created it. The original was hcfinancial@%, which is what is set below.
--
-- DEFINER
--   Kept deliberately. These objects are SQL SECURITY DEFINER, so they run with
--   the privileges of the user named in the clause, not the caller's. Setting a
--   DEFINER other than yourself needs SUPER (or SET_USER_ID), so run this as an
--   account that has it. If you cannot, remove the DEFINER clause and the object
--   is created as whoever runs the file - check that user can read every table it
--   touches before relying on it.
--
CREATE ALGORITHM=UNDEFINED DEFINER=`hcfinancial`@`%` SQL SECURITY DEFINER VIEW `cash_balances` AS select `ca`.`id` AS `CashAccount_id`,`ca`.`Name` AS `CashAccount_Name`,ifnull(`cash`.`I`,0) AS `CashAccount_I`,ifnull(`cash`.`E`,0) AS `CashAccount_E`,ifnull(`cash`.`Net`,0) AS `CashAccount_Net`,`hcsyria_financial_test`.`city`.`ID` AS `City_ID`,`hcsyria_financial_test`.`city`.`Name` AS `City_Name`,`sp`.`ID` AS `Subproject_ID`,`sp`.`Name` AS `Subproject_Name`,`cat`.`Name` AS `Category_Name`,`acc`.`ID` AS `Account_ID`,`acc`.`Name` AS `Account_Name`,`atype`.`name` AS `Account_Type`,`tt`.`Name` AS `tilltype_Name`,`acc`.`IsClosed` AS `account_IsClosed`,ifnull(`agg`.`SYR_I`,0) AS `Account_I`,ifnull(`agg`.`SYR_E`,0) AS `Account_E`,ifnull(`agg`.`SYR_I` - `agg`.`SYR_E`,0) AS `Account_Net`,ifnull(`agg`.`USD_I`,0) AS `Account_I_USD`,ifnull(`agg`.`USD_E`,0) AS `Account_E_USD`,ifnull(`agg`.`USD_I` - `agg`.`USD_E`,0) AS `Account_Net_USD` from (((((((((((`hcsyria_financial_test`.`cashaccount` `ca` left join (select `caa`.`cashaccount_id` AS `cashaccount_id`,ifnull(sum(case when `acttype`.`shortname` = 'I' then `cad`.`amount` else 0 end),0) AS `I`,ifnull(sum(case when `acttype`.`shortname` = 'E' then `cad`.`amount` else 0 end),0) AS `E`,ifnull(sum(case when `acttype`.`shortname` = 'I' then `cad`.`amount` when `acttype`.`shortname` = 'E' then -`cad`.`amount` end),0) AS `Net` from ((`hcsyria_financial_test`.`cashaction` `caa` left join `hcsyria_financial_test`.`cashaction_denominations` `cad` on(`cad`.`cashaction_id` = `caa`.`id`)) left join `hcsyria_financial_test`.`actiontype` `acttype` on(`acttype`.`id` = `cad`.`AType_id`)) group by `caa`.`cashaccount_id`) `cash` on(`cash`.`cashaccount_id` = `ca`.`id`)) left join `hcsyria_financial_test`.`cashaccount_subproject` `cas` on(`cas`.`cashaccount_id` = `ca`.`id`)) left join `hcsyria_financial_test`.`subproject` `sp` on(`sp`.`ID` = `cas`.`subproject_id`)) left join `hcsyria_financial_test`.`account` `acc` on(`acc`.`SubProject_ID` = `sp`.`ID`)) left join `hcsyria_financial_test`.`accounttype` `atype` on(`atype`.`id` = `acc`.`Accounttype_id`)) left join `hcsyria_financial_test`.`city` on(`hcsyria_financial_test`.`city`.`ID` = `sp`.`City_ID`)) left join `hcsyria_financial_test`.`project` `p` on(`p`.`ID` = `sp`.`Project_ID`)) left join `hcsyria_financial_test`.`category` `cat` on(`cat`.`ID` = `p`.`Category_ID`)) left join `hcsyria_financial_test`.`till` on(`hcsyria_financial_test`.`till`.`Account_ID` = `acc`.`ID`)) left join `hcsyria_financial_test`.`tilltypes` `tt` on(`tt`.`ID` = `hcsyria_financial_test`.`till`.`Type_ID`)) left join (select `a`.`cashaccount_id` AS `cashaccount_id`,`a`.`Till_ID` AS `Till_ID`,sum(case when `at`.`shortname` = 'I' and `tt2`.`Name` = 'SYR' then `a`.`Amount` else 0 end) AS `SYR_I`,sum(case when `at`.`shortname` in ('E','Ex') and `tt2`.`Name` = 'SYR' then `a`.`Amount` else 0 end) AS `SYR_E`,sum(case when `at`.`shortname` = 'I' and `tt2`.`Name` = 'USD' then `a`.`Amount` else 0 end) AS `USD_I`,sum(case when `at`.`shortname` in ('E','Ex') and `tt2`.`Name` = 'USD' then `a`.`Amount` else 0 end) AS `USD_E` from ((`hcsyria_financial_test`.`action` `a` left join `hcsyria_financial_test`.`actiontype` `at` on(`at`.`id` = `a`.`AType_ID`)) left join `hcsyria_financial_test`.`tilltypes` `tt2` on(`tt2`.`ID` = `a`.`currency_tilltype_id`)) group by `a`.`cashaccount_id`,`a`.`Till_ID`) `agg` on(`agg`.`cashaccount_id` = `ca`.`id` and `agg`.`Till_ID` = `hcsyria_financial_test`.`till`.`ID`)) where lcase(`tt`.`Name`) in ('syr','pay') group by `ca`.`id`,`acc`.`ID` order by `ca`.`id`;
